effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _viewport_ratio acProporcaoDoNode
vec4 u_xlat0;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat0.xy = u_xlat0.xy * _viewport_ratio.xy + vec2(0.5, 0.5);
    u_xlat0 = texture(inputImg, u_xlat0.xy);
    fragColor = u_xlat0 * _color;
    return;
}
